class Message { final String id,conversationId,senderId,content,clientMessageId; final DateTime createdAt; final DateTime? deletedAt; const Message({required this.id,required this.conversationId,required this.senderId,required this.content,required this.clientMessageId,required this.createdAt,this.deletedAt}); factory Message.fromMap(Map<String,dynamic>m)=>Message(id:m['id'],conversationId:m['conversation_id'],senderId:m['sender_id'],content:m['content'],clientMessageId:m['client_message_id'],createdAt:DateTime.parse(m['created_at']).toUtc(),deletedAt:m['deleted_at']==null?null:DateTime.parse(m['deleted_at']).toUtc());}
